    public async Task<Result<HotelBuildingDto>> CreateBuildingAsync(CreateHotelBuildingCommand command, CancellationToken ct)
    {
        var context = Context();
        if (context is null) return ContextFailure<HotelBuildingDto>();
        try
        {
            if (await repository.BuildingCodeExistsAsync(context.Property.PropertyId.Value, command.Code, null, ct))
                return Result<HotelBuildingDto>.Failure(Error.Business("HOTEL_BUILDING_CODE_CONFLICT", "Building code already exists."));
            var entity = HotelBuilding.Create(context.Property.PropertyId, command.Code, command.Name, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
            await repository.AddBuildingAsync(entity, ct);
            return await CommitBuilding(entity, "Created", ct);
        }
        catch (ArgumentException ex) { return Result<HotelBuildingDto>.Failure(Error.Validation(ex.Message, "Building input is invalid.")); }
    }

    public Task<Result<HotelBuildingDto>> UpdateBuildingAsync(UpdateHotelBuildingCommand command, CancellationToken ct) =>
        MutateBuilding(command.HotelBuildingId, command.ExpectedRowVersion, "Updated", async (entity, context) =>
        {
            if (await repository.BuildingCodeExistsAsync(context.Property.PropertyId.Value, command.Code, entity.HotelBuildingId, ct))
                throw new InvalidOperationException("HOTEL_BUILDING_CODE_CONFLICT");
            entity.Update(command.Code, command.Name, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
        }, ct);

    public Task<Result<HotelBuildingDto>> ActivateBuildingAsync(ActivateHotelBuildingCommand command, CancellationToken ct) =>
        MutateBuilding(command.HotelBuildingId, command.ExpectedRowVersion, "Activated", (entity, context) => { entity.Activate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

    public Task<Result<HotelBuildingDto>> DeactivateBuildingAsync(DeactivateHotelBuildingCommand command, CancellationToken ct) =>
        MutateBuilding(command.HotelBuildingId, command.ExpectedRowVersion, "Deactivated", (entity, context) => { entity.Deactivate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

    public async Task<Result<HotelFloorDto>> CreateFloorAsync(CreateHotelFloorCommand command, CancellationToken ct)
    {
        var context = Context();
        if (context is null) return ContextFailure<HotelFloorDto>();
        if (!await repository.BuildingExistsAsync(context.Property.PropertyId.Value, command.HotelBuildingId, true, ct))
            return Result<HotelFloorDto>.Failure(Error.Business("HOTEL_BUILDING_NOT_FOUND", "Active building was not found."));
        try
        {
            if (await repository.FloorCodeExistsAsync(context.Property.PropertyId.Value, command.HotelBuildingId, command.Code, null, ct))
                return Result<HotelFloorDto>.Failure(Error.Business("HOTEL_FLOOR_CODE_CONFLICT", "Floor code already exists in this building."));
            var entity = HotelFloor.Create(context.Property.PropertyId, command.HotelBuildingId, command.Code, command.Name, command.LevelNumber, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
            await repository.AddFloorAsync(entity, ct);
            return await CommitFloor(entity, "Created", ct);
        }
        catch (ArgumentException ex) { return Result<HotelFloorDto>.Failure(Error.Validation(ex.Message, "Floor input is invalid.")); }
    }

    public Task<Result<HotelFloorDto>> UpdateFloorAsync(UpdateHotelFloorCommand command, CancellationToken ct) =>
        MutateFloor(command.HotelFloorId, command.ExpectedRowVersion, "Updated", async (entity, context) =>
        {
            if (!await repository.BuildingExistsAsync(context.Property.PropertyId.Value, command.HotelBuildingId, true, ct))
                throw new InvalidOperationException("HOTEL_BUILDING_NOT_FOUND");
            if (await repository.FloorCodeExistsAsync(context.Property.PropertyId.Value, command.HotelBuildingId, command.Code, entity.HotelFloorId, ct))
                throw new InvalidOperationException("HOTEL_FLOOR_CODE_CONFLICT");
            entity.Update(command.HotelBuildingId, command.Code, command.Name, command.LevelNumber, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
        }, ct);

    public Task<Result<HotelFloorDto>> ActivateFloorAsync(ActivateHotelFloorCommand command, CancellationToken ct) =>
        MutateFloor(command.HotelFloorId, command.ExpectedRowVersion, "Activated", (entity, context) => { entity.Activate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

    public Task<Result<HotelFloorDto>> DeactivateFloorAsync(DeactivateHotelFloorCommand command, CancellationToken ct) =>
        MutateFloor(command.HotelFloorId, command.ExpectedRowVersion, "Deactivated", (entity, context) => { entity.Deactivate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

    public async Task<Result<HotelAreaDto>> CreateAreaAsync(CreateHotelAreaCommand command, CancellationToken ct)
    {
        var context = Context();
        if (context is null) return ContextFailure<HotelAreaDto>();
        var propertyId = context.Property.PropertyId.Value;
        if (command.HotelBuildingId is not null && !await repository.BuildingExistsAsync(propertyId, command.HotelBuildingId.Value, true, ct))
            return Result<HotelAreaDto>.Failure(Error.Business("HOTEL_BUILDING_NOT_FOUND", "Active building was not found."));
        if (command.HotelFloorId is not null && !await repository.FloorExistsAsync(propertyId, command.HotelFloorId.Value, command.HotelBuildingId, true, ct))
            return Result<HotelAreaDto>.Failure(Error.Business("HOTEL_FLOOR_NOT_FOUND", "Active floor was not found for the selected building."));
        try
        {
            if (await repository.AreaCodeExistsAsync(propertyId, command.Code, null, ct))
                return Result<HotelAreaDto>.Failure(Error.Business("HOTEL_AREA_CODE_CONFLICT", "Area code already exists."));
            var entity = HotelArea.Create(context.Property.PropertyId, command.HotelBuildingId, command.HotelFloorId, command.Code, command.Name, command.AreaType, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
            await repository.AddAreaAsync(entity, ct);
            return await CommitArea(entity, "Created", ct);
        }
        catch (ArgumentException ex) { return Result<HotelAreaDto>.Failure(Error.Validation(ex.Message, "Area input is invalid.")); }
    }

    public Task<Result<HotelAreaDto>> UpdateAreaAsync(UpdateHotelAreaCommand command, CancellationToken ct) =>
        MutateArea(command.HotelAreaId, command.ExpectedRowVersion, "Updated", async (entity, context) =>
        {
            var propertyId = context.Property.PropertyId.Value;
            if (command.HotelBuildingId is not null && !await repository.BuildingExistsAsync(propertyId, command.HotelBuildingId.Value, true, ct))
                throw new InvalidOperationException("HOTEL_BUILDING_NOT_FOUND");
            if (command.HotelFloorId is not null && !await repository.FloorExistsAsync(propertyId, command.HotelFloorId.Value, command.HotelBuildingId, true, ct))
                throw new InvalidOperationException("HOTEL_FLOOR_NOT_FOUND");
            if (await repository.AreaCodeExistsAsync(propertyId, command.Code, entity.HotelAreaId, ct))
                throw new InvalidOperationException("HOTEL_AREA_CODE_CONFLICT");
            entity.Update(command.HotelBuildingId, command.HotelFloorId, command.Code, command.Name, command.AreaType, command.Description, command.DisplayOrder, clock.UtcNow, context.Actor.ActorId);
        }, ct);

    public Task<Result<HotelAreaDto>> ActivateAreaAsync(ActivateHotelAreaCommand command, CancellationToken ct) =>
        MutateArea(command.HotelAreaId, command.ExpectedRowVersion, "Activated", (entity, context) => { entity.Activate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

    public Task<Result<HotelAreaDto>> DeactivateAreaAsync(DeactivateHotelAreaCommand command, CancellationToken ct) =>
        MutateArea(command.HotelAreaId, command.ExpectedRowVersion, "Deactivated", (entity, context) => { entity.Deactivate(clock.UtcNow, context.Actor.ActorId); return Task.CompletedTask; }, ct);

