    private async Task<Result<HotelBuildingDto>> MutateBuilding(Guid id, byte[] token, string action, Func<HotelBuilding, FrontOfficeExecutionContext, Task> mutation, CancellationToken ct)
    {
        var context = Context();
        if (context is null) return ContextFailure<HotelBuildingDto>();
        if (!ValidToken(token)) return Result<HotelBuildingDto>.Failure(Error.Validation("ROWVERSION_REQUIRED", "A row version is required."));
        var entity = await repository.GetBuildingAsync(context.Property.PropertyId.Value, id, ct);
        if (entity is null) return Result<HotelBuildingDto>.Failure(Error.Business("HOTEL_BUILDING_NOT_FOUND", "Building was not found."));
        try
        {
            repository.UseExpectedRowVersion(entity, token);
            await mutation(entity, context);
            return await CommitBuilding(entity, action, ct);
        }
        catch (ArgumentException ex) { return Result<HotelBuildingDto>.Failure(Error.Validation(ex.Message, "Building input is invalid.")); }
        catch (InvalidOperationException ex) { return Result<HotelBuildingDto>.Failure(Error.Business(ex.Message, "Building mutation is invalid.")); }
    }

