    private async Task<Result<HotelBuildingDto>> CommitBuilding(HotelBuilding entity, string action, CancellationToken ct)
    {
        persistence.StageAudit(new FrontOfficeAuditIntent(action, nameof(HotelBuilding), entity.HotelBuildingId.ToString(), "Succeeded", Metadata: new Dictionary<string, string> { ["PropertyId"] = entity.PropertyId.ToString("D") }));
        var commit = await persistence.CommitAsync(ct);
        if (commit.IsFailure) return Result<HotelBuildingDto>.Failure(commit.Error!);
        return await repository.GetBuildingDtoAsync(entity.PropertyId, entity.HotelBuildingId, ct) is { } dto
            ? Result<HotelBuildingDto>.Success(dto)
            : Result<HotelBuildingDto>.Failure(Error.System("HOTEL_BUILDING_READ_AFTER_WRITE_FAILED", "Building could not be read."));
    }

    private async Task<Result<HotelFloorDto>> CommitFloor(HotelFloor entity, string action, CancellationToken ct)
    {
        persistence.StageAudit(new FrontOfficeAuditIntent(action, nameof(HotelFloor), entity.HotelFloorId.ToString(), "Succeeded", Metadata: new Dictionary<string, string> { ["PropertyId"] = entity.PropertyId.ToString("D") }));
        var commit = await persistence.CommitAsync(ct);
        if (commit.IsFailure) return Result<HotelFloorDto>.Failure(commit.Error!);
        return await repository.GetFloorDtoAsync(entity.PropertyId, entity.HotelFloorId, ct) is { } dto
            ? Result<HotelFloorDto>.Success(dto)
            : Result<HotelFloorDto>.Failure(Error.System("HOTEL_FLOOR_READ_AFTER_WRITE_FAILED", "Floor could not be read."));
    }

